def transform(grid):
    h,w=len(grid),len(grid[0])
    counts=Counter(v for row in grid for v in row)
    bg=counts.most_common(1)[0][0]
    fg=min((v for v in counts if v!=bg), key=lambda v: counts[v])
    pts={(r,c) for r in range(h) for c in range(w) if grid[r][c]==fg}
    # Use the connected marker component, preserving its exact shape.
    start=next(iter(pts)); comp={start}; q=[start]
    while q:
        r,c=q.pop()
        for p in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
            if p in pts and p not in comp: comp.add(p);q.append(p)
    r0=min(r for r,c in comp); c0=min(c for r,c in comp)
    shape={(r-r0,c-c0) for r,c in comp}
    bh=max(r for r,c in shape)+1; bw=max(c for r,c in shape)+1
    out=[row[:] for row in grid]
    for r in range(h-bh+1):
        for c in range(w-bw+1):
            cells=[(r+dr,c+dc) for dr,dc in shape]
            if all(grid[a][b]==0 for a,b in cells):
                for a,b in cells: out[a][b]=fg
    return out
